<?php
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/csrf.php';require_admin();$items=db()->query("SELECT l.*,u.name seller,(SELECT explanation FROM fraud_predictions WHERE listing_id=l.id ORDER BY id DESC LIMIT 1) explanation FROM listings l JOIN users u ON u.id=l.user_id WHERE l.status IN ('pending','flagged') OR l.trust_status IN ('suspicious','high_risk') ORDER BY COALESCE(l.fraud_score,-1) DESC,l.created_at DESC")->fetchAll();$pageTitle='Fraud Queue';include dirname(__DIR__).'/includes/header.php';?><div class="section-head"><div><h2>Fraud Queue</h2><p>Review explainable risk scores. Admin makes the final decision.</p></div></div><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Seller</th><th>Score</th><th>Trust</th><th>Main risk</th><th>Actions</th></tr><?php foreach($items as $l):?><tr><td><a href="/listing.php?id=<?=$l['id']?>"><?=e($l['title'])?></a></td><td><?=e($l['seller'])?></td><td><?=e((string)$l['fraud_score'])?></td><td><span class="badge <?=e(trust_class($l['trust_status']??''))?>"><?=e(trust_label($l['trust_status']??''))?></span></td><td><?=e(mb_strimwidth((string)$l['explanation'],0,90,'…'))?></td><td><form method="post" action="/api/fraud.php" class="actions" style="margin:0"><?=csrf_field()?><input type="hidden" name="listing_id" value="<?=$l['id']?>"><a class="btn btn-sm btn-light" href="/listing.php?id=<?=$l['id']?>">View</a><button class="btn btn-sm" name="action" value="approve">Approve</button><button class="btn btn-sm btn-danger" name="action" value="remove">Remove</button></form></td></tr><?php endforeach;?></table></div><?php include dirname(__DIR__).'/includes/footer.php';?>